mapper.select:
/*selectMasterMpSoMonthClosingInfoList*/ SELECT MAX(Z.BUYER_NAME) AS BUYER_NAME, -- 01 MAX(Z.PO_CREATE_DATE) AS PO_CREATE_DATE, -- 02 Z.BUYER_ITEM_NO AS BUYER_ITEM_NO, -- 03 Z.PO_NO AS PO_NO, -- 04 MAX(Z.DESCRIPTION) AS DESCRIPTION, -- 05 MAX(Z.SPECIFICATION) AS SPECIFICATION, -- 06 MAX(Z.AGENT_PRICE) AS AGENT_PRICE, -- 07 MAX(Z.UNIT_MEASURE) AS UNIT_MEASURE, -- 08 MAX(NVL(Z.PO_QTY,0)) AS PO_QTY, -- 09 MAX(NVL(Z.PO_AMT,0)) AS PO_AMT, -- 10 MAX(NVL(Z.DELIVERY_QTY,0)) AS DELIVERY_QTY, -- 11 MAX(NVL(Z.DELIVERY_AMT,0)) AS DELIVERY_AMT, -- 12 MAX(NVL(Z.GR_QTY,0)) AS GR_QTY, -- 13 MAX(NVL(Z.GR_AMT,0)) AS GR_AMT, -- 14 MAX(Z.DS_DATE) AS DS_DATE, -- 15 MAX(Z.DELIVERY_DATE) AS DELIVERY_DATE, -- 16 MAX(Z.LEGACY_PO_NO) AS LEGACY_PO_NO, -- 17 Z.BUYER AS BUYER_CODE, -- 18 Z.PO_SEQ AS PO_SEQ, -- 19 MAX(Z.BYIT_COMORG_CODE) AS BYIT_COMORG_CODE,-- 20 MAX(Z.CONTRACT_NO) AS CONTRACT_NO, -- 21 MAX(Z.CONTRACT_SEQ) AS CONTRACT_SEQ, -- 22 MAX(Z.AGENT_NAME) AS AGENT_NAME, -- 23 MAX(Z.AGENT) AS AGENT_CODE, -- 24 Z.PX_NO, MAX(Z.LEGACY_PO_SEQ) AS LEGACY_PO_SEQ FROM ( SELECT X.BUYER_NAME, X.PO_CREATE_DATE, X.BUYER_ITEM_NO, X.PO_NO, X.DESCRIPTION, X.SPECIFICATION, X.AGENT_PRICE, X.UNIT_MEASURE, X.PO_QTY, X.PO_AMT, X.DELIVERY_QTY, X.DELIVERY_AMT, Y.GR_QTY, Y.GR_AMT, X.DS_DATE, X.DELIVERY_DATE, X.LEGACY_PO_NO, X.LEGACY_PO_SEQ, X.BUYER, X.PO_SEQ, X.BYIT_COMORG_CODE, X.CONTRACT_NO, X.CONTRACT_SEQ, X.AGENT_NAME, X.AGENT, X.PX_NO FROM ( SELECT MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = B.BUYER))|| MAX((SELECT '('||COM_NAME_LOC||')' FROM ICOMCMPY WHERE B.PROCESS_TYPE = '2' AND COM_CODE = DECODE(B.PROCESS_TYPE,'2',B.WAREHOUSE_CODE,B.BUYER))) AS BUYER_NAME, MAX(C.PO_CREATE_DATE) AS PO_CREATE_DATE, B.BUYER_ITEM_NO AS BUYER_ITEM_NO, B.PO_NO AS PO_NO, MAX(B.DESCRIPTION) AS DESCRIPTION, MAX(B.SPECIFICATION) AS SPECIFICATION, MAX(B.AGENT_PRICE) AS AGENT_PRICE, MAX(B.UNIT_MEASURE) AS UNIT_MEASURE, MAX(B.ITEM_QTY) AS PO_QTY, MAX(B.AGENT_ITEM_AMT) AS PO_AMT, SUM(A.DELIVERY_QTY) AS DELIVERY_QTY, MAX(B.AGENT_PRICE) * SUM(A.DELIVERY_QTY) AS DELIVERY_AMT, MAX(A.DS_DATE) AS DS_DATE, MAX(A.DELIVERY_DATE) AS DELIVERY_DATE, MAX(B.LEGACY_PO_NO) AS LEGACY_PO_NO, MAX(B.LEGACY_PO_SEQ) AS LEGACY_PO_SEQ, B.BUYER, B.PO_SEQ, MAX(B.BYIT_COMORG_CODE) AS BYIT_COMORG_CODE, MAX(B.CONTRACT_NO) AS CONTRACT_NO, MAX(B.CONTRACT_SEQ) AS CONTRACT_SEQ, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = C.AGENT)) AS AGENT_NAME, MAX(C.AGENT) AS AGENT, P.REF_NO AS PX_NO FROM ICOMIVDT A, ICOMPODT B , ICOMPOHD C , ICOMPRDT P WHERE A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND A.BUYER = C.BUYER AND A.PO_NO = C.PO_NO AND B.BUYER = P.BUYER AND B.PR_NO = P.PR_NO AND B.PR_SEQ = P.PR_SEQ AND NVL(A.DELIVERY_QTY,0) > 0 AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND P.STATUS <> 'D'
AND C.AGENT = #{st_agent_code}
AND A.BUYER = #{st_buyer_code}
AND A.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} GROUP BY B.BUYER, B.PO_NO, B.PO_SEQ, B.BUYER_ITEM_NO, P.REF_NO ) X, ( SELECT SUM(A.ITEM_QTY) AS GR_QTY, MAX(B.AGENT_PRICE) * SUM(A.ITEM_QTY) AS GR_AMT, B.BUYER, B.PO_NO, B.PO_SEQ, B.BUYER_ITEM_NO FROM ICOMGRDT A, ICOMPODT B, ICOMPOHD C WHERE A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D'
AND A.AGENT = #{st_agent_code}
AND A.BUYER = #{st_buyer_code}
AND A.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} GROUP BY B.BUYER, B.PO_NO, B.PO_SEQ, B.BUYER_ITEM_NO ) Y WHERE X.BUYER = Y.BUYER(+) AND X.PO_NO = Y.PO_NO(+) AND X.PO_SEQ = Y.PO_SEQ(+) AND X.BUYER_ITEM_NO = Y.BUYER_ITEM_NO(+)
UNION ALL
SELECT Y.BUYER_NAME, Y.PO_CREATE_DATE, Y.BUYER_ITEM_NO, Y.PO_NO, Y.DESCRIPTION, Y.SPECIFICATION, Y.AGENT_PRICE, Y.UNIT_MEASURE, Y.PO_QTY, Y.PO_AMT, X.DELIVERY_QTY, X.DELIVERY_AMT, Y.GR_QTY, Y.GR_AMT, X.DS_DATE, X.DELIVERY_DATE, Y.LEGACY_PO_NO, Y.LEGACY_PO_SEQ, Y.BUYER, Y.PO_SEQ, Y.BYIT_COMORG_CODE, Y.CONTRACT_NO, Y.CONTRACT_SEQ, Y.AGENT_NAME, Y.AGENT, Y.PX_NO FROM ( SELECT SUM(A.DELIVERY_QTY) AS DELIVERY_QTY, MAX(B.AGENT_PRICE) * SUM(A.DELIVERY_QTY) AS DELIVERY_AMT, MAX(A.DS_DATE) AS DS_DATE, MAX(A.DELIVERY_DATE) AS DELIVERY_DATE, B.BUYER, B.PO_NO, B.PO_SEQ, B.BUYER_ITEM_NO FROM ICOMIVDT A, ICOMPODT B , ICOMPOHD C WHERE A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND A.BUYER = C.BUYER AND A.PO_NO = C.PO_NO AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND NVL(A.DELIVERY_QTY,0) > 0
AND C.AGENT = #{st_agent_code}
AND A.BUYER = #{st_buyer_code}
AND A.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} GROUP BY B.BUYER, B.PO_NO, B.PO_SEQ, B.BUYER_ITEM_NO ) X, ( SELECT MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = B.BUYER))|| MAX((SELECT '('||COM_NAME_LOC||')' FROM ICOMCMPY WHERE B.PROCESS_TYPE = '2' AND COM_CODE = DECODE(B.PROCESS_TYPE,'2',B.WAREHOUSE_CODE,B.BUYER))) AS BUYER_NAME, MAX(C.PO_CREATE_DATE) AS PO_CREATE_DATE, B.BUYER_ITEM_NO AS BUYER_ITEM_NO, B.PO_NO AS PO_NO, MAX(B.DESCRIPTION) AS DESCRIPTION, MAX(B.SPECIFICATION) AS SPECIFICATION, MAX(B.AGENT_PRICE) AS AGENT_PRICE, MAX(B.UNIT_MEASURE) AS UNIT_MEASURE, MAX(B.ITEM_QTY) AS PO_QTY, MAX(B.AGENT_ITEM_AMT) AS PO_AMT, SUM(A.ITEM_QTY) AS GR_QTY, MAX(B.AGENT_PRICE) * SUM(A.ITEM_QTY) AS GR_AMT, MAX(B.LEGACY_PO_NO) AS LEGACY_PO_NO, MAX(B.LEGACY_PO_SEQ) AS LEGACY_PO_SEQ, B.BUYER, B.PO_SEQ, MAX(B.BYIT_COMORG_CODE) AS BYIT_COMORG_CODE, MAX(B.CONTRACT_NO) AS CONTRACT_NO, MAX(B.CONTRACT_SEQ) AS CONTRACT_SEQ, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = C.AGENT)) AS AGENT_NAME, MAX(C.AGENT) AS AGENT, P.REF_NO AS PX_NO FROM ICOMGRDT A, ICOMPODT B, ICOMPOHD C , ICOMPRDT P WHERE A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.BUYER = P.BUYER AND B.PR_NO = P.PR_NO AND B.PR_SEQ = P.PR_SEQ AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND P.STATUS <> 'D'
AND A.AGENT = #{st_agent_code}
AND A.BUYER = #{st_buyer_code}
AND A.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} GROUP BY B.BUYER, B.PO_NO, B.PO_SEQ, B.BUYER_ITEM_NO, P.REF_NO ) Y WHERE X.BUYER(+) = Y.BUYER AND X.PO_NO(+) = Y.PO_NO AND X.PO_SEQ(+) = Y.PO_SEQ AND X.BUYER_ITEM_NO(+) = Y.BUYER_ITEM_NO ) Z GROUP BY Z.BUYER, Z.PO_NO, Z.PO_SEQ , Z.BUYER_ITEM_NO, Z.PX_NO ORDER BY Z.BUYER, Z.PO_NO, Z.PO_SEQ
